   135→            *SIGNED_BEACON_BLOCK_ALTAIR_MAX, // Altair block is larger than base blocks
   136→        ),
   137→        // After the merge the max SSZ size of a block is absurdly big. The size is actually
   138→        // bound by other constants, so here we default to the bellatrix's max value
   139→        _ => RpcLimits::new(
   140→            *SIGNED_BEACON_BLOCK_BASE_MIN, // Base block is smaller than altair and bellatrix blocks
   141→            *SIGNED_BEACON_BLOCK_BELLATRIX_MAX, // Bellatrix block is larger than base and altair blocks
   142→        ),
   143→    }
   144→}
