  1071→                        {
  1072→                            blobs_sent += 1;
  1073→                            self.send_network_message(NetworkMessage::SendResponse {
  1074→                                peer_id,
  1075→                                inbound_request_id,
  1076→                                response: Response::BlobsByRange(Some(blob_sidecar.clone())),
  1077→                            });
  1078→                        }
  1079→                    }
  1080→                }
  1081→                Err(e) => {
  1082→                    error!(
  1083→                        request = ?req,
  1084→                        %peer_id,
  1085→                        block_root = ?root,
  1086→                        error = ?e,
  1087→                        "Error fetching blobs block root"
  1088→                    );
  1089→                    log_results(peer_id, req, blobs_sent);
  1090→
  1091→                    return Err((
  1092→                        RpcErrorResponse::ServerError,
  1093→                        "No blobs and failed fetching corresponding block",
  1094→                    ));
  1095→                }
  1096→            }
  1097→        }
